27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "membership_number")
61	    private String membershipNumber;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @Column(name = "membership_level")
73	    private Integer membershipLevel;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public LocalDate getRegistrationDate() {
111	        return this.registrationDate;
112	    }
113	
114	    public void setRegistrationDate(LocalDate registrationDate) {
115	        this.registrationDate = registrationDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    public void setCustomerCode(String customerCode) {
123	        this.customerCode = customerCode;
124	    }
125	
126	    public String getMembershipNumber() {
127	        return this.membershipNumber;
128	    }
129	
130	    public void setMembershipNumber(String membershipNumber) {
131	        this.membershipNumber = membershipNumber;
132	    }
133	
134	    public String getHouseholdId() {
135	        return this.householdId;
136	    }
137	
138	    public void setHouseholdId(String householdId) {
139	        this.householdId = householdId;
140	    }
141	
142	    public Integer getNamesakeCount() {
143	        return this.namesakeCount;
144	    }
145	
146	    public void setNamesakeCount(Integer namesakeCount) {
147	        this.namesakeCount = namesakeCount;
148	    }
149	
150	    public Integer getHouseholdSize() {
151	        return this.householdSize;
152	    }
153	
154	    public void setHouseholdSize(Integer householdSize) {
155	        this.householdSize = householdSize;
156	    }
157	
158	    public Integer getMembershipLevel() {
159	        return this.membershipLevel;
160	    }
161	
162	    public void setMembershipLevel(Integer membershipLevel) {
163	        this.membershipLevel = membershipLevel;
164	    }
165	
166	    /**
167	     * The owner's locality: the canonical region derived from the city via the fixed
168	     * {@link CityRegion} table, or {@code "UNKNOWN"} when the city is not in the table.
169	     */
170	    @Transient
171	    public String getLocality() {
172	        return CityRegion.of(this.city);
173	    }
174	
175	    /**
176	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
177	     * present, otherwise {@code "PHONE"}.
178	     */
179	    @Transient
180	    public String getContactPreference() {
181	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
182	    }
183	
184	    protected Set<Pet> getPetsInternal() {
185	        if (this.pets == null) {
186	            this.pets = new HashSet<>();
187	        }
188	        return this.pets;
189	    }
190	
191	    protected void setPetsInternal(Set<Pet> pets) {
192	        this.pets = pets;
193	    }
194	
195	    public List<Pet> getPets() {
196	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
197	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
198	        return Collections.unmodifiableList(sortedPets);
199	    }
200	
201	    public void setPets(List<Pet> pets) {
202	        this.pets = new HashSet<>(pets);
203	    }
204	
205	    public void addPet(Pet pet) {
206	        getPetsInternal().add(pet);
207	        pet.setOwner(this);
208	    }
209	
210	    /**
211	     * Return the Pet with the given name, or null if none found for this Owner.
212	     *
213	     * @param name to test
214	     * @return true if pet name is already in use
215	     */
216	    public Pet getPet(String name) {
217	        return getPet(name, false);
218	    }
219	
220	    /**
221	     * Return the Pet with the given name, or null if none found for this Owner.
222	     *
223	     * @param name to test
224	     * @return true if pet name is already in use
225	     */
226	    public Pet getPet(String name, boolean ignoreNew) {
227	        name = name.toLowerCase();
228	        for (Pet pet : getPetsInternal()) {
229	            if (!ignoreNew || !pet.isNew()) {
230	                String compName = pet.getName();
231	                compName = compName.toLowerCase();
232	                if (compName.equals(name)) {
233	                    return pet;
234	                }
235	            }
236	        }
237	        return null;
238	    }
239	
240	    public Pet getPet(Integer petId) {
241	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
242	    }
243	
244	    @Override
245	    public String toString() {
246	        return new ToStringCreator(this)
247	
248	            .append("id", this.getId())
249	            .append("new", this.isNew())
250	            .append("lastName", this.getLastName())
251	            .append("firstName", this.getFirstName())
252	            .append("address", this.address)
253	            .append("city", this.city)
254	            .append("telephone", this.telephone)
255	            .toString();
256	    }
257	}
