3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
7	
8	/**
9	 * Rejects a create-owner request whose normalized telephone is already used by another owner, before
10	 * {@link BuildOwner} runs. Runs after {@link NormalizeOwnerTelephone} so the request holds the E.164
11	 * value that matches how owner telephones are persisted, making the comparison E.164-based. Rejects
12	 * with 409 otherwise.
13	 */
14	public class EnsureUniqueTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateTelephoneException {
18	        if (!ownerRepository.findByTelephone(request.getTelephone()).isEmpty()) {
19	            throw new DuplicateTelephoneException(request.getTelephone());
20	        }
21	    }
22	}
