2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create-owner request that would add a second owner to a household already occupied by an
11	 * existing owner — one sharing the same last name and address (see {@link Household}). A request may
12	 * opt in to sharing a household by setting {@code sharesHousehold} true, which skips the check (the
13	 * shared {@code householdId} is then assigned by {@link AssignHousehold}). Rejects with 409 otherwise.
14	 */
15	public class EnsureUniqueHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
20	            return;
21	        }
22	        for (Owner existing : ownerRepository.findByLastName(request.getLastName())) {
23	            if (Household.matches(existing, request.getLastName(), request.getAddress())) {
24	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
25	            }
26	        }
27	    }
28	}
