1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
8	import org.springframework.util.StringUtils;
9	
10	/**
11	 * Normalizes the optional email of an owner request in place: when present it must be a
12	 * syntactically valid address, and is stored lower-cased. An absent (or blank) email is
13	 * left untouched, since email is optional. Rejects a present-but-invalid email with 400.
14	 */
15	public class NormalizeOwnerEmail {
16	
17	    /** local-part '@' domain, no spaces, and a dotted domain. */
18	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
19	
20	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
21	        String email = request.getEmail();
22	        if (!StringUtils.hasText(email)) {
23	            return;
24	        }
25	        if (!EMAIL.matcher(email).matches()) {
26	            throw new InvalidEmailException(email);
27	        }
28	        request.setEmail(email.toLowerCase());
29	    }
30	}
