3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Shared address normalization for created owners: trims and collapses whitespace, upper-cases,
8	 * and expands common street-type abbreviations ({@code ST->STREET}, {@code RD->ROAD},
9	 * {@code AVE->AVENUE}). Used to store and return an owner's address in canonical form (see
10	 * {@link NormalizeOwnerAddress}), to reject an address that is blank once normalized
11	 * ({@link ValidateRequiredOwnerFields}) and to compare addresses for household identity
12	 * ({@link Household}).
13	 */
14	final class AddressNormalizer {
15	
16	    /** Street-type abbreviations expanded to their full word, keyed by their upper-cased token. */
17	    private static final Map<String, String> ABBREVIATIONS = Map.of(
18	            "ST", "STREET",
19	            "RD", "ROAD",
20	            "AVE", "AVENUE");
21	
22	    private AddressNormalizer() {
23	    }
24	
25	    /**
26	     * The normalized form of an address: leading/trailing and repeated inner whitespace collapsed to
27	     * a single space, upper-cased, and each known street-type abbreviation expanded. A {@code null}
28	     * or all-whitespace address normalizes to the empty string.
29	     */
30	    static String normalize(String address) {
31	        if (address == null) {
32	            return "";
33	        }
34	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
35	        if (collapsed.isEmpty()) {
36	            return "";
37	        }
38	        String[] tokens = collapsed.split(" ");
39	        StringBuilder normalized = new StringBuilder();
40	        for (int i = 0; i < tokens.length; i++) {
41	            if (i > 0) {
42	                normalized.append(' ');
43	            }
44	            normalized.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
45	        }
46	        return normalized.toString();
47	    }
48	}
