     * @param telephone the normalized telephone to match
     * @return the matching <code>Owner</code>s (empty if none)
     */
    Collection<Owner> findByTelephone(String telephone) throws DataAccessException;

    /**
     * Retrieve every <code>Owner</code> whose stored email matches the given value case-insensitively.
     * Used to enforce email uniqueness on create; the value passed is already lower-cased, matching how
     * owner emails are normalized before being persisted through the REST API.
     *
     * @param email the lower-cased email to match
     * @return the matching <code>Owner</code>s (empty if none)
     */
    Collection<Owner> findByEmail(String email) throws DataAccessException;


    /**
     * Save an <code>Owner</code> to the data store, either inserting or updating it.
     *
     * @param owner the <code>Owner</code> to save
     * @see BaseEntity#isNew
     */
    void save(Owner owner) throws DataAccessException;

    /**
     * Count the total number of <code>Owner</code>s in the data store.
     *
     * @return the number of persisted owners
     */
    long count() throws DataAccessException;

    /**
     * Count the number of <code>Owner</code>s in the data store located in the given city.
     * Used to build the per-city sequence embedded in an owner's {@code customerCode}.
     *
     * @param city the city to match exactly
     * @return the number of persisted owners in that city
     */
    long countByCity(String city) throws DataAccessException;

    /**
     * Count the number of <code>Owner</code>s registered on the given date.
     * Used to enforce the per-day cap on newly created owners.
     *
     * @param registrationDate the registration date to match exactly
     * @return the number of persisted owners registered on that date
     */
    long countByRegistrationDate(LocalDate registrationDate) throws DataAccessException;

    /**
     * Retrieve <code>Owner</code>s from the data store, returning all owners
     *
     * @return a <code>Collection</code> of <code>Owner</code>s (or an empty <code>Collection</code> if none
     * found)
     */
	Collection<Owner> findAll() throws DataAccessException;

    Page<Owner> findAll(Pageable pageable) throws DataAccessException;

    /**
     * Delete an <code>Owner</code> to the data store by <code>Owner</code>.
     *
     * @param owner the <code>Owner</code> to delete
     * 
     */
	void delete(Owner owner) throws DataAccessException;


